async function api(path,options={}){const headers={'content-type':'application/json',...(accessToken?{authorization:`Bearer ${accessToken}`}:{}) ,...(options.headers||{})};let r;try{r=await fetch(path,{...options,headers})}catch{throw Error('Cannot reach BackendDev on this page. Open the public app URL and refresh.')};let d={};try{d=await r.json()}catch{}if(!r.ok){const code=d.error_code||d.code||'';const detail=d.msg||d.message||d.error_description||d.error?.message||(typeof d.error==='string'?d.error:'');if(code==='invalid_credentials')throw Error('Email or password is incorrect. If you just created the account, confirm the email first, then sign in.');if(code==='email_not_confirmed')throw Error('Confirm your email using the link Supabase sent, then sign in.');if(code==='app_auth_rate_limited')throw Error(detail);if(code==='over_email_send_rate_limit'||/email rate limit exceeded|email.*rate limit/i.test(detail)){const error=Error('Supabase has reached its shared email limit. No password reset email was sent. The owner must configure a custom email sender in Supabase; retrying now will not help.');error.code='email_provider_rate_limited';throw error}if(r.status===429||code==='rate_limit_exceeded'||/too many requests|rate limit/i.test(detail))throw Error('Sign-in was temporarily rate limited. Wait a few minutes before retrying. This does not mean your account is banned; do not keep submitting attempts.');if(code==='user_already_exists'||/already registered|already exists/i.test(detail))throw Error('This email already has an account. Choose “Sign in” instead.');throw Error(detail||`Request failed (${r.status})`)}return d}
async function syncProjects(){
  try{
    const health=await api('/api/health');cloudStorageReady=Boolean(health.multiUserReady);
    document.querySelector('#serverStatus').textContent=cloudStorageReady?'Cloud configured':'Local storage';document.querySelector('#serverMode').textContent=cloudStorageReady?'Sign in to sync this device':'Saved on this computer';
    if(!accessToken){projects=[];renderProjects();renderActivity();updateProfile();return}
    if(!cloudStorageReady){throw Error('Sign-in is required, but Supabase is not configured on this BackendDev server. Add its URL and publishable key, then restart the app.')}
    const remote=await api('/api/projects');
    if(cloudStorageReady){
      const local=loadProjects().filter(project=>project.localOnly),unsynced=[];projects=remote;
      for(const project of local){try{const saved=await api('/api/projects',{method:'POST',body:JSON.stringify(project)});projects.push(saved);recordActivity(`${project.name} synced to your account`,'Local project copied to cloud')}catch{unsynced.push(project)}}
      projects.push(...unsynced);saveProjects();
    }else projects=[...seeds,...remote.filter(project=>!seeds.some(seed=>seed.id===project.id))];
    renderProjects();renderActivity();updateProfile();
  }catch(error){
    document.querySelector('#serverStatus').textContent='Offline';document.querySelector('#serverMode').textContent='Could not reach the BackendDev server';
    if(/please sign in|session expired/i.test(error.message)){accessToken='';sessionStorage.removeItem('backenddev.accessToken');updateProfile();openAuthDialog()}
    else if(!accessToken){projects=[];renderProjects();renderActivity();updateProfile();notify('Sign in to use BackendDev. If this page will not load, start the app with npm start.')}
    else notify(error.message);
  }
}
