async function finishAuthenticatedLogin(data){if(!data?.access_token)throw Error('Authentication did not return a valid session. Try signing in again.');accessToken=data.access_token;sessionStorage.setItem('backenddev.accessToken',accessToken);pendingMfaLogin=null;document.querySelector('#mfaChallengeDialog').close();authDialog.close();await syncProjects();updateProfile();refreshRuntimes()}
