async function showProjectActions(project){
  if(!requireSignIn())return;
  if (seeds.some(s=>s.id===project.id)) { notify('Sample projects are read-only. Create a project to edit files.'); return; }
  const action=prompt(`Project: ${project.name}\nType DELETE to remove this project.`);
  if(action==='DELETE'){if(!project.localOnly){try{await api(`/api/projects/${project.id}`,{method:'DELETE'})}catch(error){notify(`Could not delete project: ${error.message}`);return}}projects=projects.filter(p=>p.id!==project.id);saveProjects();renderProjects();notify(`${project.name} deleted.`)}
}
