const passwordChecks={length:value=>value.length>=12,lower:value=>/[a-z]/.test(value),upper:value=>/[A-Z]/.test(value),number:value=>/[0-9]/.test(value),symbol:value=>/[^A-Za-z0-9]/.test(value)};
