form.addEventListener('submit',async event=>{
  if(event.submitter?.value==='cancel')return;
  event.preventDefault();
  if(!requireSignIn())return;
  if(!form.reportValidity())return;
  const name=nameInput.value.trim();
  if(projects.some(project=>project.name.toLowerCase()===name.toLowerCase())){notify('A project with that name already exists.');return}
  const [language,framework]=stackSelect.value.split(' · ');
  const idea=document.querySelector('#projectIdea').value.trim()||'Create a basic health API.';
  const resource=resourceForIdea(idea),files=createStarterFiles(language,name,idea);
  let savedLocally=false;
  const project={name,language,framework,status:'Draft',description:idea,files,updated:'Created just now'};
  try{const saved=await api('/api/projects',{method:'POST',body:JSON.stringify(project)});projects.push(saved)}
  catch(error){if(accessToken){notify(`Could not save project to your account: ${error.message}`);return}project.id=crypto.randomUUID();project.localOnly=true;projects.push(project);saveProjects();savedLocally=true;notify('Project saved in this browser. Sign in later to sync it to your account.')}
  renderProjects();dialog.close();recordActivity(`${name} created`,`${language} · ${framework} · /health and /${resource}`);
  if(project.id&&!savedLocally)notify(`${name} created and saved.`);
});
