async function pollRun(){if(!activeRun)return;try{const result=await api(`/api/run/${activeRun.id}`);document.querySelector('#checkOutput').textContent=`${result.running?'Backend is running':'Process exited with code '+result.exitCode}\n${result.output||'(waiting for output)'}`;if(!result.running){recordActivity(`${activeRun.name} stopped`,`Exit code ${result.exitCode}`);activeRun=null;document.querySelector('#runCheck').textContent='Run backend';clearTimeout(runPollTimer);return}}catch(error){document.querySelector('#checkOutput').textContent=error.message;activeRun=null;document.querySelector('#runCheck').textContent='Run backend';return}runPollTimer=setTimeout(pollRun,700)}
