function decodeProposal(text){if(text&&typeof text==='object')return text;const raw=String(text||'').trim(),cleaned=raw.replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');try{return JSON.parse(cleaned)}catch{const first=cleaned.indexOf('{'),last=cleaned.lastIndexOf('}');if(first>=0&&last>first)return JSON.parse(cleaned.slice(first,last+1));throw Error('The model reply was not valid JSON. Try again with a smaller, more specific change.')}}
document.querySelector('#assistantForm').addEventListener('submit',async e=>{e.preventDefault();if(!requireSignIn())return;const input=document.querySelector('#assistantInput'),submit=e.submitter||document.querySelector('#assistantForm button');if(!input.value.trim())return;const out=document.querySelector('#aiOutput');out.textContent='Contacting your model…';document.querySelector('#applyAi').hidden=true;submit.disabled=true;submit.textContent='Generating…';try{const project=projects.find(p=>p.id===currentProjectId);if(!project)throw Error('Open a project before asking AI to change it.');const result=await api('/api/generate',{method:'POST',body:JSON.stringify({prompt:input.value,files:project.files||{}})});const proposal=decodeProposal(result.answer);if(!proposal.files||typeof proposal.files!=='object'||Array.isArray(proposal.files)||!Object.keys(proposal.files).length)throw Error('The model response did not contain any proposed files. Ask for a specific file or feature.');for(const [file,content] of Object.entries(proposal.files)){if(typeof content!=='string'||file.startsWith('/')||file.split(/[\\/]/).includes('..'))throw Error('The model returned an invalid file path or file content. Please try a more specific request.')}proposedFiles=proposal.files;out.textContent=`${proposal.summary||'Proposed changes'}\n\n${Object.entries(proposedFiles).map(([file,content])=>`--- ${file} ---\n${content}`).join('\n\n')}`;document.querySelector('#applyAi').hidden=false;recordActivity(project.name+' AI proposal ready',Object.keys(proposedFiles).length+' files proposed')}catch(err){proposedFiles=null;out.textContent=`Could not generate a proposal. ${err.message}`}finally{submit.disabled=false;submit.textContent='Generate'}});
document.querySelector('#applyAi').addEventListener('click',async()=>{if(!requireSignIn()||!proposedFiles)return;const project=projects.find(p=>p.id===currentProjectId);if(!project)return;const next={...project.files};for(const [file,content] of Object.entries(proposedFiles)){if(file.startsWith('/')||file.split(/[\\/]/).includes('..')){notify(`Rejected unsafe file path: ${file}`);return}next[file]=String(content)}try{if(!project.localOnly)await api(`/api/projects/${project.id}`,{method:'PUT',body:JSON.stringify({files:next})});project.files=next;saveProjects();proposedFiles=null;document.querySelector('#applyAi').hidden=true;const select=document.querySelector('#fileSelect'),old=select.value,files=Object.keys(project.files);select.replaceChildren(...files.map(file=>{const o=document.createElement('option');o.value=file;o.textContent=file;return o}));select.value=files.includes(old)?old:files[0];select.dispatchEvent(new Event('change'));document.querySelector('#aiOutput').textContent='Changes applied and saved. Review files in the selector.';recordActivity(`${project.name} AI changes applied`,`${Object.keys(next).length} files in project`);notify('AI changes applied and saved.')}catch(error){notify(`Could not save AI changes: ${error.message}`)}});
