document.querySelector('#sendApiRequest').addEventListener('click',async()=>{if(!requireSignIn())return;const out=document.querySelector('#apiOutput'),raw=document.querySelector('#apiUrl').value.trim(),method=document.querySelector('#apiMethod').value,bodyText=document.querySelector('#apiBody').value.trim();let target;try{target=new URL(raw);if(!['http:','https:'].includes(target.protocol))throw Error()}catch{out.textContent='Enter a valid http:// or https:// API URL.';return}let payload;try{if(bodyText)payload=JSON.parse(bodyText)}catch{out.textContent='Request body must be valid JSON.';return}out.textContent='Sending request…';const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000),started=performance.now();try{const response=await fetch(target,{method,signal:controller.signal,headers:payload?{'content-type':'application/json'}:undefined,body:payload?JSON.stringify(payload):undefined});const text=await response.text();out.textContent=`${response.status} ${response.statusText} · ${Math.round(performance.now()-started)} ms\n\n${text.slice(0,20000)||'(empty response)'}`;recordActivity('API request sent',`${method} ${target.host} · ${response.status}`)}catch(error){out.textContent=error.name==='AbortError'?'Request timed out after 15 seconds.':`Request blocked or failed: ${error.message}. The target must be online and allow browser CORS requests.`;recordActivity('API request failed',`${method} ${target.host}`)}finally{clearTimeout(timer)}});
