async function loadAdminUsers(){
  const host=document.querySelector('#adminUsers'),status=document.querySelector('#adminStatus');host.textContent='Loading accounts…';
  try{
    const data=await api('/api/admin/users');document.querySelector('#adminUserCount').textContent=String(data.users.length);host.replaceChildren();
    if(!data.users.length){host.textContent='No accounts found.';return}
    for(const user of data.users){
      const row=document.createElement('article');row.className='admin-row';const info=document.createElement('span'),email=document.createElement('b'),meta=document.createElement('small'),actions=document.createElement('div');actions.className='admin-actions';
      email.textContent=user.email||'No email';meta.textContent='Created '+(user.createdAt?new Date(user.createdAt).toLocaleDateString():'unknown')+' · '+(user.confirmedAt?'Email confirmed':'Email unconfirmed')+(user.lastSignInAt?' · Last sign-in '+new Date(user.lastSignInAt).toLocaleDateString():'');info.append(email,meta);
      const suspended=Boolean(user.bannedUntil&&new Date(user.bannedUntil)>new Date()),toggle=document.createElement('button');toggle.type='button';toggle.className='outline';toggle.textContent=suspended?'Restore access':'Suspend';
      toggle.addEventListener('click',async()=>{toggle.disabled=true;try{await api('/api/admin/users/'+encodeURIComponent(user.id)+'/'+(suspended?'restore':'suspend'),{method:'POST',body:'{}'});status.textContent=(user.email||'Account')+' '+(suspended?'restored':'suspended')+'.';await loadAdminUsers()}catch(error){status.textContent=error.message;toggle.disabled=false}});
      const remove=document.createElement('button');remove.type='button';remove.className='outline danger-action';remove.textContent='Delete account';
      remove.addEventListener('click',async()=>{if(!confirm('Permanently delete '+(user.email||'this account')+' and its owned project rows? This cannot be undone.'))return;remove.disabled=true;try{await api('/api/admin/users/'+encodeURIComponent(user.id),{method:'DELETE'});status.textContent=(user.email||'Account')+' deleted.';await Promise.all([loadAdminUsers(),loadAdminProjects()])}catch(error){status.textContent=error.message;remove.disabled=false}});
      actions.append(toggle,remove);row.append(info,actions);host.append(row);
    }
  }catch(error){host.textContent='Could not load accounts.';status.textContent=error.message}
}
async function viewAdminProject(projectId){
  const dialog=document.querySelector('#adminProjectDialog'),title=document.querySelector('#adminProjectTitle'),meta=document.querySelector('#adminProjectMeta'),select=document.querySelector('#adminProjectFile'),content=document.querySelector('#adminProjectContent');
  title.textContent='Loading project…';meta.textContent='Fetching private project details';select.replaceChildren();content.textContent='';dialog.showModal();
  try{const result=await api('/api/admin/projects/'+encodeURIComponent(projectId)),project=result.project;title.textContent=project.name;meta.textContent=project.language+' · '+project.framework+' · owner '+project.owner_id+' · '+project.status;const files=Object.entries(project.files||{});if(!files.length){select.disabled=true;content.textContent='This project has no saved files.';return}select.disabled=false;select.replaceChildren(...files.map(([file])=>{const option=document.createElement('option');option.value=file;option.textContent=file;return option}));const showFile=()=>{content.textContent=String(project.files[select.value]??'')};select.onchange=showFile;showFile()}catch(error){meta.textContent=error.message;content.textContent='Could not load project files.'}
}
