      title.textContent=item.subject;meta.textContent=item.category+' · '+item.user_email+' · '+(item.created_at?new Date(item.created_at).toLocaleString():'date unknown');message.textContent=item.message;info.append(title,meta,message);actions.className='feedback-actions';
      if(item.user_email){const reply=document.createElement('a');reply.className='outline';reply.href='mailto:'+encodeURIComponent(item.user_email)+'?subject='+encodeURIComponent('BackendDev feedback: '+item.subject);reply.textContent='Reply by email';actions.append(reply)}
      for(const optionText of ['New','In review','Resolved']){const option=document.createElement('option');option.value=optionText;option.textContent=optionText;select.append(option)}select.value=item.status;select.setAttribute('aria-label','Set status for '+item.subject);select.addEventListener('change',async()=>{const chosen=select.value;select.disabled=true;try{await api('/api/admin/feedback/'+encodeURIComponent(item.id),{method:'PUT',body:JSON.stringify({status:chosen})});item.status=chosen;document.querySelector('#adminOpenFeedbackCount').textContent=String([...host.querySelectorAll('.feedback-row')].filter(node=>node.querySelector('select')?.value!=='Resolved').length);status.textContent='Feedback marked '+chosen.toLowerCase()+'.'}catch(error){status.textContent=error.message;select.value=item.status}finally{select.disabled=false}});
      actions.append(select);row.append(info,actions);host.append(row);
